module div_8bit (
    input wire clk,
    input wire rst,
    input wire [7:0] dividend,
    input wire [7:0] divisor,
    input wire sign,
    input wire opn_valid,
    output reg res_valid,
    input wire res_ready,
    output reg [15:0] result
);

reg [7:0] abs_dividend;
reg [7:0] abs_divisor;
reg [15:0] quotient;
reg [7:0] remainder;
reg [7:0] temp_quotient;
reg [7:0] temp_remainder;
reg [2:0] shift_count;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        res_valid <= 0;
        quotient <= 0;
        remainder <= 0;
        shift_count <= 0;
    end else if (opn_valid && res_ready) begin
        abs_dividend <= sign ? -dividend : dividend;
        abs_divisor <= sign ? -divisor : divisor;
        quotient <= 0;
        remainder <= abs_dividend;
        shift_count <= 7;

        while (shift_count >= 0) begin
            temp_remainder = {remainder[6:0], 1'b0};
            if (temp_remainder >= abs_divisor) begin
                temp_remainder = temp_remainder - abs_divisor;
                temp_quotient = 1 << shift_count;
            end else begin
                temp_quotient = 0;
            end
            quotient = quotient | temp_quotient;
            remainder = temp_remainder;
            shift_count = shift_count - 1;
        end

        if (sign && ((dividend ^ divisor) < 0)) begin
            quotient = -quotient;
        end

        result = {quotient, remainder};
        res_valid <= 1;
    end else begin
        res_valid <= 0;
    end
end

endmodule
